R=Path(__file__).resolve().parents[2];E=R/'evidence/beta06/generation03';inputs={}
def digest(b):return hashlib.sha256(b).hexdigest()
def read(name):
 p=E/name;b=p.read_bytes();inputs[name]={'bytes':len(b),'sha256':digest(b),'classification':'PERSISTED_LIVE_PREFIX_AT_QA_REVIEW'if p.suffix=='.jsonl'else'RETAINED_ROOT_CAPTURE'};return b

def chain(name):
 b=read(name);assert b.endswith(b'\n');rows=[];head='0'*64
 for line in b.splitlines():
  r=json.loads(line);assert r['seq']==len(rows)+1 and r['previousSha256']==head;assert digest(re.sub(rb',"sha256":"[a-f0-9]{64}"}$',b'}',line))==r['sha256'];head=r['sha256'];rows.append(r)
 inputs[name].update(records=len(rows),head=head);return rows
failure=json.loads(read('g3-ground-n1-restaged-ground-soak.json'));samples=failure['samples'];assert failure['error']=='STALE_OBSERVATION'and failure['status']=='REFUSED_GROUND_ADMISSION_NO_AP'and len(samples)==133
